// Pure production planner metadata for tool-admission rows. No FIR allocation.
#include "dsp/resampler.h"
#include <fstream>
#include <iomanip>
int main(int argc,char**argv){try{if(argc!=5)return 2;auto*p=rta::dsp::find_preset(argv[1]);if(!p)return 2;rta::dsp::ResamplerConfig c;c.inRate=std::stoul(argv[2]);c.outRate=std::stoul(argv[3]);c.channels=2;c.autoTaps=true;c.allowAutomaticCascade=true;rta::dsp::apply_preset(c,*p);c=rta::dsp::resolve_auto_taps(c);auto plan=rta::dsp::plan_resampler(c);bool fixed=double(plan.stages[0].T)*plan.stages[0].config.outRate*2<=250e6;c.useFixed=fixed;plan=rta::dsp::plan_resampler(c);std::ofstream o(argv[4]);o<<std::setprecision(17)<<"{\"scope\":\"pure shared production planner only, no actual coefficients or numeric quality\",\"planned_fixed_eligible\":"<<(fixed?"true":"false")<<",\"L\":"<<plan.L<<",\"M\":"<<plan.M<<",\"planned_coefficient_count\":"<<plan.coefficientCount<<",\"planner_peak_bytes\":"<<plan.designPeakBytes<<",\"stages\":[";
for(size_t i=0;i<plan.stageCount;++i){if(i)o<<",";const auto&s=plan.stages[i];const auto&v=s.config;o<<"{\"L\":"<<s.L<<",\"M\":"<<s.M<<",\"T\":"<<s.T<<",\"count\":"<<s.coefficientCount<<",\"input_rate\":"<<v.inRate<<",\"output_rate\":"<<v.outRate<<",\"coefficient_rate\":"<<uint64_t(v.inRate)*s.L<<",\"reference_gain\":"<<s.L<<",\"base_cutoff_norm_nyquist\":"<<std::min(1./s.L,1./s.M)*(1-v.transition*.5)<<",\"phase\":"<<std::quoted(rta::dsp::phase_name(v.phase))<<",\"window\":"<<std::quoted(rta::dsp::window_name(v.window))<<",\"phase_mix\":"<<v.designPhaseMix<<",\"useFixed\":"<<(v.useFixed?"true":"false")<<"}";}o<<"]}";return !o;}catch(...){return 2;}}
